      "mainEntity": [
        {
          "@type": "Question",
          "name": "Does our associations' data ever leave our environment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Deepvine is deployed inside your firm's own infrastructure, and your governing documents, minutes, financials, homeowner records, and prompts stay there. Nothing is copied to a shared cloud, and your inputs are never used to train an outside model."
          }
        },
        {
          "@type": "Question",
          "name": "Will it make up covenant answers like consumer AI tools do?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Deepvine answers only from your documents and cites the source document, section, and page for every answer. If the governing documents do not address a question, it says so directly instead of guessing."
          }
        },
        {
          "@type": "Question",
          "name": "Can it read old scanned declarations and amendments?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Deepvine processes scanned PDFs, including declarations, amendments, and minutes from the 1980s and 1990s, and makes them searchable alongside your current records."
          }
        },
        {
          "@type": "Question",
          "name": "Do we need an IT department to run this?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Deepvine handles deployment, maintenance, and updates as part of the engagement. Most community association management firms run it with no internal IT staff."
          }
        },
        {
          "@type": "Question",
          "name": "How is this different from our document portal?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Portals store documents. Deepvine understands them. Instead of locating the right PDF and reading two hundred pages, your team asks a plain-language question and gets the cited answer in seconds."
          }
        },
        {
          "@type": "Question",
          "name": "What does it cost?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pricing depends on the size of your firm, the number of associations under management, and the depth of historical document backfill, so we scope it during the demo rather than list a single number. The engagement is structured as an ongoing managed service that includes deployment, maintenance, and updates."
          }
        }
      ]
